import { teacherSubjectClasses } from "./academic-portal.js";
import { button, badge, emptyState, escapeHtml as e } from "./ui.js";
import { icon } from "./icons.js";
import { panel, metric, select, table } from "./chairman.js";
import { coursesPage } from "./learning.js";
import { subjectViews, subjectScope, subjectCourses, subjectOverview, subjectCourseProgress, subjectEnrolments, subjectPlans, subjectSupportRequests, subjectReportTypes, subjectPlanStatuses, subjectReviewStatuses, subjectSupportTypes, visibleSubjectReports } from "./subject-data.js";

const choices = (values, current) => values.map(([id, name]) => `<option value="${e(id)}" ${String(id) === String(current) ? "selected" : ""}>${e(name)}</option>`).join("");
const heading = (title, text, actions = "") => `<header class="chairman-page-heading"><div><h1>${title}</h1><p>${text}</p></div><div class="chairman-heading-actions">${badge("Prototype", "amber")}${actions}</div></header>`;
const footer = (label) => `<p class="form-error" role="alert" hidden></p><footer class="dialog-actions">${button("Cancel", "close-dialog", { variant: "secondary" })}<button class="button primary" type="submit">${label}</button></footer>`;
const link = (view, text) => `<a class="button secondary compact" href="#teacher/overview/${view}">${text}</a>`;
const history = (notes) => notes?.length ? `<div class="vice-note-history"><h3>Previous notes</h3>${notes.map((note) => `<article><p>${e(note.text)}</p><small>${e(note.by)} · ${e(note.at.slice(0, 10))}</small></article>`).join("")}</div>` : "";
function identity(options, scope) {
  const entries = options.state.accounts.flatMap((person) => person.grants.map((grant, index) => ({ person, grant, index }))).filter(({ grant }) => grant.role === "teacher");
  const selected = options.context.account.id + "|" + options.context.account.grants.indexOf(options.context.grant);
  return `<header class="section-identity"><div><span class="chairman-eyebrow">SUBJECT TEACHER WORKSPACE</span><h1>${e(scope.account.name)}</h1><p>${e(scope.branch.school)} · ${scope.courses.length} assigned teaching subject${scope.courses.length === 1 ? "" : "s"}</p></div><label class="principal-demo-account"><span>Demo Subject Teacher</span><span class="select-wrap"><select data-change="account" aria-label="Preview Subject Teacher">${choices(entries.map(({ person, grant, index }) => [person.id + "|" + index, person.name + " · " + options.state.branches.find((branch) => branch.id === grant.branch)?.name]), selected)}</select>${icon("chevronDown", 14)}</span></label></header>`;
}
function filters(options, kind) {
  const f = options.subjectTeacher, courses = subjectCourses(options.state, options.context);
  return `<div class="chairman-filters subject-filters">${select("Assigned subject", "subject-course", [["all", "All my teaching subjects"], ...courses.map((course) => [course.id, course.title + " · Class " + course.className])], f.course)}${kind === "progress" ? select("Learning review", "subject-review-filter", [["all", "All review statuses"], ["unreviewed", "Not reviewed"], ...Object.entries(subjectReviewStatuses)], f.review) + `<label class="chairman-search">${icon("search", 16)}<input type="search" aria-label="Search enrolled students" data-change="subject-query" data-focus="subject-search" value="${e(f.query)}" placeholder="Student, admission or subject"></label>` : ""}${kind === "plans" ? select("Lesson plan status", "subject-plan-filter", [["all", "All plans"], ...Object.entries(subjectPlanStatuses)], f.planStatus) : ""}</div>`;
}
function courseTable(options) {
  const courses = subjectCourses(options.state, options.context, options.subjectTeacher);
  return courses.length ? table(["Subject", "Enrolled", "Materials", "Done / assigned", "Actions"], courses.map((course) => { const p = subjectCourseProgress(options.state, options.context, course); return `<tr><td><strong>${e(course.title)}</strong><small>Class ${e(course.className)} · ${e(course.code)}</small></td><td>${p.enrolled}</td><td>${p.materials}</td><td>${p.completed} / ${p.expected}</td><td><div class="section-row-actions">${button("View materials", "open-course", { value: course.id, variant: "secondary compact" })}${button("Add material", "add-material", { value: course.id, variant: "secondary compact", iconName: "plus" })}</div></td></tr>`; }).join(""), "Assigned teaching subjects") : emptyState("book", "No assigned subjects", "Leadership assigns teaching subjects and enrolled students.");
}
function overview(options) {
  const data = subjectOverview(options.state, options.context);
  return heading("Subject Overview", "Your teaching subjects, learning readiness and next classroom priorities.", link("teaching", "Open teaching workspace")) + `<div class="chairman-metrics">${metric("Assigned subjects", data.courses.length, "Current teaching assignments", "book")}${metric("Enrolled students", data.students, data.enrolments + " subject enrolments", "users", "blue")}${metric("Published materials", data.materials, "Available in enrolled parent portals", "file")}${metric("Learning completion", data.completion === null ? "—" : data.completion + "%", data.completed + " / " + data.expected + " material assignments", "checkCircle")}</div><div class="section-summary-strip"><div><span>Lesson plans</span><strong>${data.plans.length}</strong></div><div><span>Needs practice</span><strong>${data.needsPractice}</strong></div><div><span>Subjects without materials</span><strong>${data.courses.filter((course) => !options.state.materials.some((item) => item.course === course.id)).length}</strong></div><div><span>Open support requests</span><strong>${data.requests.filter((item) => item.status !== "resolved").length}</strong></div></div><div class="section-attention"><div><h2>Teaching priorities</h2><p>Review student learning, prepare the next lesson and follow up coordinator responses.</p></div>${link("progress", "Review student progress")}</div>` + panel("My teaching subjects", "Assignments and enrolment are managed by academic leadership", teacherSubjectClasses(options));
}
function teaching(options) {
  if (subjectCourses(options.state, options.context).some((course) => course.id === options.courseId)) return coursesPage(options);
  const f = options.subjectTeacher, plans = subjectPlans(options.state, options.context, f), courses = subjectCourses(options.state, options.context);
  return heading("Teaching & Materials", "Publish lecture notes, worksheets and reading for your assigned subjects.", courses.length ? button("New lesson plan", "subject-plan-new", { value: f.course === "all" ? "" : f.course, iconName: "plus" }) : "") + filters(options, "plans") + panel("Subject materials", "Download or edit existing materials, and publish files up to 2 MB", courseTable(options)) + panel("Lesson plans", "20–27 Nov 2026 · Internal teaching preparation", plans.length ? table(["Subject / class", "Lesson topic", "Planned date", "Status", "Action"], plans.map((item) => { const course = courses.find((course) => course.id === item.course); return `<tr><td><strong>${e(course.title)}</strong><small>Class ${e(course.className)}</small></td><td>${e(item.topic)}</td><td>${e(item.date)}</td><td>${badge(subjectPlanStatuses[item.status], item.status === "completed" ? "green" : "blue")}</td><td>${button("Update lesson plan", "subject-plan-edit", { value: item.id, variant: "secondary compact" })}</td></tr>`; }).join(""), "Teaching lesson plans") : emptyState("book", "No lesson plans in this selection", "Create a plan for an assigned subject to prepare the next lesson."));
}
function progress(options) {
  const rows = subjectEnrolments(options.state, options.context, options.subjectTeacher);
  return heading("Student Progress", "Review completion recorded by parents and record a staff learning review.") + filters(options, "progress") + panel("Enrolled student learning", "Learning reviews are internal staff records. Completion is recorded through the parent portal.", rows.length ? table(["Student", "Subject / class", "Materials done", "Learning review", "Action"], rows.map((row) => `<tr><td><strong>${e(row.student.name)}</strong><small>${e(row.student.admissionNumber)}</small></td><td>${e(row.course.title)}<small>Class ${e(row.course.className)}</small></td><td>${row.completed} / ${row.materials}<progress value="${row.completed}" max="${row.materials || 1}" aria-label="${e(row.student.name)} ${e(row.course.title)} completion"></progress></td><td>${badge(subjectReviewStatuses[row.review?.status] || "Not reviewed", row.review?.status === "needs_practice" ? "amber" : "neutral")}${row.review?.notes[0] ? `<small class="subject-review-note">${e(row.review.notes[0].text)}</small>` : ""}</td><td>${button("Review learning", "subject-review", { value: row.course.id + "|" + row.student.id, variant: "secondary compact" })}</td></tr>`).join(""), "Enrolled student progress") : emptyState("users", "No enrolled students match", "Try another assigned subject or review filter."));
}
function support(options) {
  if (subjectCourses(options.state, options.context).some((course) => course.id === options.courseId)) return coursesPage(options);
  const courses = subjectCourses(options.state, options.context, options.subjectTeacher), requests = subjectSupportRequests(options.state, options.context, options.subjectTeacher);
  return heading("Teaching Support", "Coordinate learning concerns, lecture materials and teaching cover with your Grade Coordinator.", subjectCourses(options.state, options.context).length ? button("Request coordinator support", "subject-support", { value: options.subjectTeacher.course === "all" ? "" : options.subjectTeacher.course, iconName: "plus" }) : "") + filters(options, "support") + panel("Requests and coordinator responses", "Requests stay with the subject’s school and grade", `<div class="grade-support-grid">${requests.map((item) => `<article class="grade-support-card"><div>${badge(subjectSupportTypes[item.type], "blue")}${badge(({open:"Open",in_progress:"In progress",resolved:"Resolved"})[item.status], item.status === "resolved" ? "green" : "amber")}</div><h3>${e(item.title)} · Class ${e(item.className)}</h3><p>${e(item.note)}</p><small>${e(item.by)}</small>${item.responses.length ? `<div class="grade-response"><strong>Grade Coordinator response</strong>${item.responses.map((response) => `<p>${e(response.text)}</p><small>${e(response.by)} · ${e(response.at.slice(0, 10))}</small>`).join("")}</div>` : '<p class="chairman-filter-note">Awaiting coordinator review</p>'}</article>`).join("") || emptyState("checkCircle", "No teaching requests", "Record a subject-specific request for your Grade Coordinator.")}</div>`) + panel("Section Head material feedback", "Read the latest readiness feedback, then update your subject materials", courses.length ? table(["Subject", "Material readiness", "Feedback", "Action"], courses.map((course) => { const review = options.state.sectionCourseReviews?.[course.id]; return `<tr><td><strong>${e(course.title)}</strong><small>Class ${e(course.className)}</small></td><td>${review ? review.status === "ready" ? "Ready for learning" : "Updates requested" : "Not reviewed"}</td><td>${e(review?.note || "Awaiting Section Head review")}</td><td>${button("View materials", "open-course", { value: course.id, variant: "secondary compact" })}</td></tr>`; }).join(""), "Teaching readiness feedback") : emptyState("book", "No assigned subjects", "Feedback appears for your current teaching subjects."));
}
export function subjectReportPreview(report) {
  const c = report.criteria, s = report.summary;
  return `<article class="subject-report-preview section-report-preview"><div class="section-report-brand"><strong>School Management Platform</strong>${badge("SAMPLE · PROTOTYPE", "amber")}</div><h2>${e(report.title)}</h2><p>${e(report.owner.school)} · Subject Teacher: ${e(report.owner.teacher)}</p><p>Snapshot: ${e(c.to)} · ${e(c.courseLabels.join(", ") || "No assigned subjects")}</p>${report.type === "progress" ? `<p>Learning review: ${e(subjectReviewStatuses[c.review] || (c.review === "unreviewed" ? "Not reviewed" : "All review statuses"))} · Search: ${e(c.query || "All enrolled students")}</p>` : ""}${report.type === "plans" ? `<p>Plan status: ${e(subjectPlanStatuses[c.planStatus] || "All plans")} · Planning window: 20–27 Nov 2026</p>` : ""}<div class="section-summary-strip"><div><span>Subjects</span><strong>${s.courses}</strong></div><div><span>Enrolled students</span><strong>${s.students}</strong></div><div><span>Materials</span><strong>${s.materials}</strong></div><div><span>Done / assigned</span><strong>${s.completed} / ${s.expected}</strong></div></div>${table(report.customColumns.map(([, label]) => label), report.customRows.map((row) => `<tr>${report.customColumns.map(([key]) => `<td>${e(row[key])}</td>`).join("")}</tr>`).join(""), "Subject report data")}<p class="chairman-filter-note">Current prototype records at capture time. Learning completion is parent-recorded. Internal free-text review and support notes are excluded. Subject and student access are checked again when opening saved reports.</p></article>`;
}
export function subjectReportHTML(report, logo = "") {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(report.title)} · School Management Platform</title><style>body{font:14px Arial,sans-serif;color:#183a32;max-width:1120px;margin:36px auto;padding:0 24px}img{width:66px;float:right}h2{font-size:27px}table{width:100%;border-collapse:collapse;margin:24px 0}td,th{text-align:left;border-bottom:1px solid #dce6e1;padding:10px}th{background:#edf4f0}.table-scroll{overflow:auto}.section-summary-strip{display:flex;justify-content:space-between;gap:20px;background:#edf4f0;padding:20px}.section-summary-strip span{display:block;font-size:12px}.section-summary-strip strong{font-size:22px}.chairman-filter-note{color:#52685f;font-size:12px}.badge{display:inline-block;margin:8px;color:#825414}@media print{body{margin:0;max-width:none}tr{break-inside:avoid}thead{display:table-header-group}}@page{size:A4 landscape;margin:14mm}</style></head><body>${logo ? `<img alt="School Management Platform logo" src="${e(logo)}">` : ""}${subjectReportPreview(report)}<footer>Subject Teacher’s workspace · Generated ${e(report.generatedAt)} · UI demonstration</footer></body></html>`;
}
function reports(options, scope) {
  const f = options.subjectTeacher, reports = visibleSubjectReports(options.state, options.context), current = reports.find((report) => report.id === f.reportId);
  return heading("Subject Reports", "Capture teaching readiness and enrolled-student learning for academic coordination.") + `<div class="section-report-builder surface"><div>${select("Report type", "subject-report-type", Object.entries(subjectReportTypes), f.reportType)}</div>${filters(options, f.reportType === "progress" ? "progress" : f.reportType === "plans" ? "plans" : "reports")}<div class="section-report-generate"><p>${icon("school", 17)}${e(scope.branch.name)} · Your teaching subjects</p>${button("Generate subject report", "subject-generate-report", { iconName: "file" })}</div></div><section class="surface chairman-report-result"><div class="chairman-report-actions">${current ? select("Download format", "subject-report-format", [["csv", "CSV spreadsheet"], ["html", "Standalone HTML"]], f.reportFormat) + button("Download report", "subject-download-report", { value: current.id, variant: "secondary", iconName: "download" }) + button("Print / Save PDF", "subject-print-report", { value: current.id, variant: "secondary", iconName: "file" }) : "Report preview"}</div>${current ? subjectReportPreview(current) : emptyState("file", "Your subject report starts here", "Choose a report and teaching subject, then generate a snapshot.")}</section>` + panel("Saved teaching snapshots", "Latest eight per teacher and school · Reports outside your current subject or student access are hidden", `<div class="chairman-report-history">${reports.map((item) => `<button type="button" class="chairman-history-card ${current?.id === item.id ? "is-selected" : ""}" data-action="subject-open-report" data-value="${item.id}">${icon("file", 20)}<span><strong>${e(item.title)}</strong><small>${e(item.criteria.to)} · ${item.customRows.length} rows</small></span>${badge("Sample", "neutral")}</button>`).join("") || '<p class="chairman-no-history">Generated subject reports will appear here.</p>'}</div>`);
}
export function subjectTeacherPage(options) {
  const scope = subjectScope(options.state, options.context);
  if (!scope) return emptyState("book", "No Subject Teacher appointment", "An active school appointment is required.");
  const view = options.subjectTeacher.view;
  return `<section class="chairman-portal section-portal subject-teacher-portal">${identity(options, scope)}<nav class="chairman-view-bar section-view-bar" aria-label="Subject Teacher views">${subjectViews.map((item) => `<a href="#teacher/overview/${item.id}" aria-label="${item.name}" ${item.id === view ? 'aria-current="page" class="is-active"' : ""}>${icon(item.icon, 18)}<span class="chairman-view-full">${item.name}</span><span class="chairman-view-short">${item.short}</span></a>`).join("")}</nav><div class="chairman-analytics section-analytics">${scope.courses.some((course) => course.id === options.courseId) ? coursesPage(options) : ({ summary: overview, teaching, progress, support, reports })[view](options, scope)}</div></section>`;
}
export function subjectPlanForm(options, previous = null, courseId = "") {
  const courses = subjectCourses(options.state, options.context), course = courses.find((course) => course.id === previous?.course);
  return `<form data-form="subject-plan"><div class="form-body"><input type="hidden" name="id" value="${e(previous?.id || "")}">${previous ? `<input type="hidden" name="course" value="${e(course.id)}"><h3>${e(course.title)} · Class ${e(course.className)}</h3>` : `<label class="field">Assigned subject<select name="course" required>${choices(courses.map((course) => [course.id, course.title + " · Class " + course.className]), courseId)}</select></label>`}<label class="field">Lesson topic<input name="topic" maxlength="120" required value="${e(previous?.topic || "")}"></label><label class="field">Planned date<input name="date" type="date" min="2026-11-20" max="2026-11-27" value="${e(previous?.date || "2026-11-23")}" required></label><label class="field">Plan status<select name="status">${choices(Object.entries(subjectPlanStatuses), previous?.status || "planned")}</select></label><label class="field">Lesson outline / update<textarea name="note" maxlength="1000" rows="4" required></textarea></label>${history(previous?.notes)}<p class="chairman-filter-note">Internal teaching preparation for this subject. Publish student-facing lecture notes separately.</p></div>${footer("Save lesson plan")}</form>`;
}
export function subjectReviewForm(row) {
  return `<form data-form="subject-review"><div class="form-body"><input type="hidden" name="course" value="${e(row.course.id)}"><input type="hidden" name="student" value="${e(row.student.id)}"><h3>${e(row.student.name)}</h3><p>${e(row.course.title)} · Class ${e(row.course.className)} · ${row.completed} / ${row.materials} materials done</p><label class="field">Learning review status<select name="status">${choices(Object.entries(subjectReviewStatuses), row.review?.status || "on_track")}</select></label><label class="field">Internal learning note<textarea name="note" maxlength="1000" rows="4" required></textarea></label>${history(row.review?.notes)}<p class="chairman-filter-note">Visible to staff with access to this subject, including its next assigned teacher. Parent completion and assessment marks are separate.</p></div>${footer("Save learning review")}</form>`;
}
